<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{api,session}from'../api';const data=ref<any>(null),usage=ref<any>(null),loading=ref(true),error=ref('');const list=computed(()=>Object.entries(data.value?.features||{}).map(([code,value])=>({code,...(value as any)})));const opened=computed(()=>list.value.filter(x=>x.enabled));const closed=computed(()=>list.value.filter(x=>!x.enabled));async function load(){loading.value=true;error.value='';try{[data.value,usage.value]=await Promise.all([api('/api/v2/organization/bootstrap'),api('/api/v2/organization/usage')]);session.bootstrap=data.value}catch(e:any){error.value=e.message}finally{loading.value=false}}onMounted(load);</script>
<template><div class="page-stack"><div v-if="loading" class="panel state-inline">正在获取企业配置……</div><div v-else-if="error" class="panel state-inline error"><b>暂时无法加载设置</b><span>{{error}}</span><button @click="load">立即重试</button></div><template v-else><section class="panel"><header class="panel-head"><div><span class="eyebrow">SUBSCRIPTION & CAPABILITIES</span><h2>功能模块与用量</h2><p>查看当前套餐、已开通能力和使用限制。未购买功能需要联系平台开通。</p></div><span class="plan">{{data.organization.plan_code}}</span></header><div class="usage-grid"><article v-for="(x,key) in usage" :key="key"><span>{{String(key)==='devices'?'设备':String(key)==='rooms'?'直播间':'成员'}}</span><strong>{{x.used}} / {{x.limit}}</strong><i><em :style="{width:`${Math.min(100,x.used/Math.max(1,x.limit)*100)}%`}"></em></i></article></div></section><section class="panel"><header class="panel-head"><div><h3>已开通功能</h3><p>这些功能可以直接使用。</p></div><span class="quota">{{opened.length}} 项</span></header><div class="feature-grid"><article v-for="x in opened" :key="x.code"><span class="feature-check">✓</span><div><b>{{x.name}}</b><small>{{x.source==='trial'?'试用中':x.source==='plan'?'套餐包含':'已开通'}}</small></div></article></div></section><section class="panel"><header class="panel-head"><div><h3>暂未开通</h3><p>企业管理员不能自行开启未购买功能。</p></div></header><div class="feature-grid muted"><article v-for="x in closed" :key="x.code"><span class="feature-check">—</span><div><b>{{x.name}}</b><small>{{x.reason==='minimum_version'?'需要升级客户端':'联系平台了解开通方式'}}</small></div></article></div></section></template></div></template>
